field.eval:
[
  {
    "type": "start",
    "config": {"variables": []}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "account.move",
      "domain": [["move_type", "=", "in_invoice"], ["payment_state", "in", ["not_paid", "partial"]]],
      "fields": ["name", "partner_id", "amount_residual", "invoice_date_due"],
      "limit": 15,
      "order": "invoice_date_due asc"
    }},
    "resultVariable": "bills"
  },
  {
    "type": "agent",
    "config": {"instruction": "Summarize the unpaid vendor bills in ${bills}: vendor, invoice number, amount owed and due date. Flag the most overdue first."},
    "resultVariable": "summary"
  },
  {
    "type": "output",
    "config": {"value": "${summary}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": []}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "sale.order",
      "domain": [["state", "=", "sale"]],
      "fields": ["name", "partner_id", "amount_total", "date_order"],
      "limit": 10,
      "order": "date_order desc"
    }},
    "resultVariable": "orders"
  },
  {
    "type": "agent",
    "config": {"instruction": "Summarize these recent sales in ${orders}: order, customer, total and date. End with the combined total."},
    "resultVariable": "digest"
  },
  {
    "type": "output",
    "config": {"value": "${digest}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": []}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "sale.order",
      "domain": [["state", "=", "draft"]],
      "fields": ["name", "partner_id", "amount_total", "create_date"],
      "limit": 15,
      "order": "create_date asc"
    }},
    "resultVariable": "drafts"
  },
  {
    "type": "agent",
    "config": {"instruction": "List these draft quotations in ${drafts} for follow-up: quote, customer, amount and age. Oldest first."},
    "resultVariable": "followups"
  },
  {
    "type": "output",
    "config": {"value": "${followups}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": [
      {"name": "since", "type": "required", "description": "Show leads created on or after this date (YYYY-MM-DD)"}
    ]}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "crm.lead",
      "domain": [["create_date", ">=", "${since}"]],
      "fields": ["name", "partner_id", "email_from", "phone", "stage_id"],
      "limit": 20,
      "order": "create_date desc"
    }},
    "resultVariable": "leads"
  },
  {
    "type": "agent",
    "config": {"instruction": "Triage these new leads in ${leads}: name, contact, stage, and which look hottest. One line each."},
    "resultVariable": "triage"
  },
  {
    "type": "output",
    "config": {"value": "${triage}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": [
      {"name": "since", "type": "required", "description": "Show hours logged on or after this date (YYYY-MM-DD)"}
    ]}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "account.analytic.line",
      "domain": [["date", ">=", "${since}"]],
      "fields": ["project_id", "task_id", "employee_id", "unit_amount", "date"],
      "limit": 30,
      "order": "date desc"
    }},
    "resultVariable": "lines"
  },
  {
    "type": "agent",
    "config": {"instruction": "Summarize these timesheet lines in ${lines} by project: hours logged and who worked. End with the week total."},
    "resultVariable": "summary"
  },
  {
    "type": "output",
    "config": {"value": "${summary}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": []}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "product.template",
      "domain": [["list_price", "<=", 0]],
      "fields": ["name", "list_price", "type", "categ_id"],
      "limit": 20
    }},
    "resultVariable": "products"
  },
  {
    "type": "agent",
    "config": {"instruction": "List these zero-priced products in ${products} for review: name, type, and whether a zero price looks intentional (e.g. a service) or like missing data."},
    "resultVariable": "review"
  },
  {
    "type": "output",
    "config": {"value": "${review}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": [
      {"name": "before", "type": "required", "description": "Tasks due on or before this date (YYYY-MM-DD)"}
    ]}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "project.task",
      "domain": [["date_deadline", "<=", "${before}"]],
      "fields": ["name", "project_id", "user_ids", "date_deadline", "stage_id"],
      "limit": 20,
      "order": "date_deadline asc"
    }},
    "resultVariable": "tasks"
  },
  {
    "type": "agent",
    "config": {"instruction": "List these overdue tasks in ${tasks}: task, project, owner, deadline and stage. Oldest first."},
    "resultVariable": "blockers"
  },
  {
    "type": "output",
    "config": {"value": "${blockers}"}
  }
]

[
  {
    "type": "start",
    "config": {"variables": [
      {"name": "before", "type": "required", "description": "Drafts created on or before this date (YYYY-MM-DD)"}
    ]}
  },
  {
    "type": "search",
    "config": {"args": {
      "model": "account.move",
      "domain": [["state", "=", "draft"], ["create_date", "<=", "${before}"]],
      "fields": ["name", "move_type", "partner_id", "amount_total", "create_date"],
      "limit": 20,
      "order": "create_date asc"
    }},
    "resultVariable": "drafts"
  },
  {
    "type": "agent",
    "config": {"instruction": "List these stale drafts in ${drafts} for cleanup: type, partner, amount and age. Oldest first."},
    "resultVariable": "cleanup"
  },
  {
    "type": "output",
    "config": {"value": "${cleanup}"}
  }
]
